 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Template is the existing contiguous five-cell horizontal object. The
    # isolated marker color is the remaining non-background color.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    template = None
    template_colors = set()
    for row in grid:
        for c in range(w - 4):
            vals = row[c:c+5]
            if all(v != background for v in vals) and len(set(vals)) > 1:
                template = vals[:]
                template_colors = set(vals)
                break
        if template is not None:
            break
    if template is None:
        raise ValueError('template not found')
    marker_colors = {v for v in counts if v != background and v not in template_colors}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in marker_colors:
                for k, value in enumerate(template):
                    cc = c + k - 2
                    if 0 <= cc < w:
                        out[r][cc] = value
    return out
